 for(unsigned algorithm=0;algorithm<8;++algorithm){check(fmCarrierMask(uint8_t(algorithm))==carriers[algorithm],"original algorithm carrier masks");for(unsigned channel=0;channel<6;++channel){FmInstrument value={};for(unsigned i=0;i<25;++i)value.source[i]=uint8_t(i+1);value.source[0]=uint8_t(0x28+algorithm);check(encodeFmInstrument(channel,value,writes,error)&&writes.size()==25,"all6voices and8algorithms patch extent");check(writes[0].part==channel/3&&writes[0].address==0xb0+channel%3&&writes[0].value==value.source[0],"source algorithm and feedback");const unsigned offsets[]={0,8,4,12};for(unsigned op=0;op<4;++op)for(unsigned parameter=0;parameter<6;++parameter){const FmSynthWrite& w=writes[1+op*6+parameter];uint8_t expected=parameter==1&&(carriers[algorithm]&(1u<<op))?255:value.source[1+op*6+parameter];check(w.part==channel/3&&w.address==0x30+offsets[op]+channel%3+16*parameter&&w.value==expected,"source operator permutation, carrier muting and parameter mapping");}}}
 check(fmCarrierMask(8)==0&&fmCarrierMask(255)==0,"unknown algorithms are not guessed");
 for(unsigned channel=0;channel<6;++channel){for(uint16_t frequency:{uint16_t(0),uint16_t(1),uint16_t(255),uint16_t(256),uint16_t(0x3fff)}){check(encodeFmFrequency(channel,frequency,writes,error)&&writes.size()==2&&writes[0].part==channel/3&&writes[0].address==0xa4+channel%3&&writes[0].value==frequency>>8&&writes[1].address==0xa0+channel%3&&writes[1].value==uint8_t(frequency),"high frequency latch precedes low source frequency");}check(encodeFmKey(channel,true,writes,error)&&writes[0].part==0&&writes[0].address==0x28&&writes[0].value==0xf0+(channel<3?channel:channel+1),"source6voice key routing");check(encodeFmKey(channel,false,writes,error)&&writes[0].value==(channel<3?channel:channel+1),"keyoff preserves source channel");check(encodeFmPan(channel,0xf7,writes,error)&&writes[0].address==0xb4+channel%3&&writes[0].value==0xf7,"pan andfullhardware modulation field preserved");uint8_t levels[4]={0,1,64,127};check(encodeFmLevels(channel,levels,writes,error)&&writes[1].address==0x48+channel%3&&writes[2].address==0x44+channel%3,"source operator level permutation");}
 for(unsigned channel=0;channel<6;++channel){check(encodeFmFastRelease(channel,writes,error)&&writes.size()==5,"fast release exact source extent");for(unsigned op=0;op<4;++op)check(writes[op].part==channel/3&&writes[op].address==0x80+4*op+channel%3&&writes[op].value==0xff,"fast release source RR write order");check(writes[4].part==0&&writes[4].address==0x28&&writes[4].value==(channel<3?channel:channel+1),"fast release falls through source keyoff");}
 for(unsigned algorithm=0;algorithm<8;++algorithm)for(unsigned channel=0;channel<6;++channel){uint8_t levels[4]={11,22,33,44};check(encodeFmCarrierLevels(channel,levels,carriers[algorithm],writes,error),"source carrier-only dynamic level writes");unsigned count=0;for(unsigned op=0;op<4;++op)if(carriers[algorithm]&(1u<<op))++count;check(writes.size()==count,"modulator level not rewritten by note/gain changes");unsigned at=0;const unsigned offsets[]={0,8,4,12};for(int op=3;op>=0;--op)if(carriers[algorithm]&(1u<<op)){const FmSynthWrite& w=writes[at++];check(w.part==channel/3&&w.address==0x40+offsets[op]+channel%3&&w.value==levels[op],"source dynamic carrier writes preserve exact descending operator chronology");}}
 std::vector<FmSynthWrite> prior=writes;check(!encodeFmFrequency(0,0x4000,writes,error)&&writes.size()==prior.size()&&writes[0].value==prior[0].value,"invalid frequency rejects transactionally");check(!encodeFmKey(6,true,writes,error)&&!encodeFmPan(99,0,writes,error),"invalid channels reject");uint8_t bad[4]={0,0,128,0};check(!encodeFmLevels(0,bad,writes,error)&&!encodeFmLevels(0,nullptr,writes,error),"invalid attenuation rejects");
 FmOutputCoupling coupling;int64_t priorStep=1000*65536;check(coupling.process(priorStep,44100)==priorStep,"coupling step begins at input with no fitted gain");
 for(unsigned i=0;i<16384;++i){int64_t now=coupling.process(INT64_C(1000)*65536,44100);check(now>=0&&now<=priorStep,"source-derived coupling decays DC monotonically");priorStep=now;}
 check(priorStep<65536,"constant DC decays below one S16 unit");coupling.reset();check(coupling.process(0,44100)==0&&coupling.process(1000*65536,44100)==1000*65536,"coupling reset eliminates previous signal history");
 NativeFmSynthRenderer whole,partitioned;startTone(whole,0xc0,error);startTone(partitioned,0xc0,error);std::vector<int16_t> actual,expected,chunk;check(whole.renderPcm(44100,expected,error),"one bounded synthetic tone render");const unsigned sizes[]={1,735,736,17,4096,3,31,882};unsigned cursor=0;while(cursor<44100){unsigned count=sizes[cursor%8];if(count>44100-cursor)count=44100-cursor;check(partitioned.renderPcm(count,chunk,error),"variable callback pull");actual.insert(actual.end(),chunk.begin(),chunk.end());cursor+=count;}check(actual==expected,"sample and bus timing independent of callback partition");check(whole.renderedFrames()==44100&&partitioned.renderedFrames()==44100&&!whole.pendingWrites(),"render extent and pending writes settle");size_t nonzero=0;for(size_t i=0;i<expected.size();i+=2){nonzero+=expected[i]!=0;check(expected[i]==expected[i+1],"centerpan stereo output equal");}check(nonzero>1000,"backend produces real nonzero sound");
 // No render call is a precise pause; reset drops old bus/output state.
 std::vector<int16_t> nextA,nextB;check(whole.renderPcm(441,nextA,error)&&partitioned.renderPcm(441,nextB,error)&&nextA==nextB,"paused owner resumes at identical synthesis state");startTone(partitioned,0xc0,error);check(partitioned.renderPcm(44100,actual,error)&&actual==expected,"reset/replay drops stale output and is deterministic");
 NativeFmSynthRenderer silent;check(silent.renderPcm(4096,actual,error)&&std::find_if(actual.begin(),actual.end(),[](int16_t v){return v!=0;})==actual.end(),"fresh unkeyed output is digital silence");
