 NativeFmSynthRenderer invalid(0);check(!invalid.init(error)&&!invalid.renderPcm(1,actual,error),"invalid constructor sample rate rejects without allocation fault");prior=writes;actual=expected;check(!whole.renderPcm(0,actual,error)&&actual==expected&&!whole.renderPcm(1000001,actual,error)&&actual==expected,"render bounds preserve output on failure");
 if(argc==3&&std::string(argv[1])=="--tone"){std::ofstream out(argv[2],std::ios::binary);for(int16_t sample:expected){char bytes[2]={char(uint16_t(sample)),char(uint16_t(sample)>>8)};out.write(bytes,2);}check(bool(out),"private synthetic tone export");}else if(argc!=1)return 2;
